pub fn save_scene_text(
    fs: &dyn FileSystemPort,
    project_root: &str,
    rel_path: &str,
    text: &str,
) -> Result<String, HostError> {
    let rel = normalize_scene_rel(Some(rel_path), DEFAULT_SGS_REL)?;
    let path = join_project_rel(project_root, &rel)?;
    if let Some(parent) = std::path::Path::new(&path).parent() {
        let parent_s = parent.to_string_lossy();
        if !parent_s.is_empty() {
            fs.create_dir_all(&parent_s)
                .map_err(|e| HostError::Settings(format!("mkdir for scene save: {e}")))?;
        }
    }
    fs.write_atomic(&path, text.as_bytes())
        .map_err(|e| HostError::Settings(format!("write scene file: {e}")))?;
    Ok(path)
}

pub fn capture(&self) -> Result<ImmutableDocumentSnapshot, EditError> {
    self.check_editable()?;
    Ok(ImmutableDocumentSnapshot {
        document_uuid: self.state.document_uuid.clone(),
        session_uuid: self.state.session_uuid.clone(),
        revision: self.state.content_revision,
        content: self.state.content.clone(),
    })
}

pub fn acknowledge_formal_save(
    &mut self,
    captured: Revision,
    digest: &str,
) -> Result<SaveProjection, EditError> {
    self.check_ack(captured, digest, self.state.formal_baseline.as_ref())?;
    self.state.formal_baseline = Some(SavedContentBaseline {
        revision: captured,
        semantic_digest: digest.into(),
    });
    Ok(SaveProjection {
        captured_revision: captured,
        dirty: self.dirty(),
    })

pub fn acknowledge_recovery_save(
    &mut self,
    captured: Revision,
    digest: &str,
) -> Result<RecoveryProjection, EditError> {
    self.check_ack(captured, digest, self.state.snapshot_baseline.as_ref())?;
    self.state.snapshot_baseline = Some(SavedContentBaseline {
        revision: captured,
        semantic_digest: digest.into(),
    });
    Ok(RecoveryProjection {
        captured_revision: captured,
        needs_snapshot: self.state.content.semantic_digest != digest,
    })

fn check_ack(
    &self,
    captured: Revision,
    digest: &str,
    baseline: Option<&SavedContentBaseline>,
) -> Result<(), EditError> {
    self.check_editable()?;
    if !valid_digest(digest) {
        return Err(EditError::InvalidInput {
            field: "semanticDigest".into(),
        });
    }
    if captured.0 > self.state.content_revision.0
        || (captured == self.state.content_revision
            && digest != self.state.content.semantic_digest)
        || baseline.is_some_and(|saved| {
            captured.0 < saved.revision.0
                || (captured == saved.revision && digest != saved.semantic_digest)
        })
    {
        return Err(EditError::RevisionConflict);
    }
    Ok(())
}

fn dirty(&self) -> bool {
    self.state
        .formal_baseline
        .as_ref()
        .map(|saved| saved.semantic_digest != self.state.content.semantic_digest)
        .unwrap_or(true)

//! M05-S1 pure retention policy. No physical cleanup behavior.
//! Root projections are supplied by their authoritative owners through HOST.
//! Eligibility is never permission to delete; no paths, leases or IO enter here.

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AssetCandidate {
    pub asset_id: String,
    pub content_digest: String,
    pub owned_by_operation: Option<String>,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RootKind {
    LiveDocuments,
    UndoHistory,
    RedoHistory,
    RecoverySnapshots,
    InFlightTransactions,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Completeness {
    Complete,
    Unknown,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RootReference {
    pub asset_id: String,
    pub content_digest: String,
    pub owner_id: String,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RootObservation {
    pub kind: RootKind,
    pub revision: String,
    pub completeness: Completeness,
    pub references: Vec<RootReference>,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RootSnapshot {
    pub project_id: String,
    pub session_id: String,
    pub observations: Vec<RootObservation>,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EvaluationContext {
    pub project_id: String,
    pub session_id: String,
    pub operation_id: String,
    pub expected_root_revisions: Vec<(RootKind, String)>,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetentionDecision {
    Retain {
        reasons: Vec<RetentionReason>,
    },
    EligibleForCleanup {
        asset_id: String,
        content_digest: String,
    },

let mut reasons = Vec::new();
for kind in [
    RootKind::LiveDocuments,
    RootKind::UndoHistory,
    RootKind::RedoHistory,
    RootKind::RecoverySnapshots,
    RootKind::InFlightTransactions,
] {
    let i = root_index(kind);
    let Some(observation) = observed[i] else {
        reasons.push(RetentionReason::RootsIncomplete { kind });
        continue;
    };
    if observation.completeness == Completeness::Unknown || expected[i].is_none() {
        reasons.push(RetentionReason::RootsIncomplete { kind });
    } else if expected[i] != Some(observation.revision.as_str()) {
        reasons.push(RetentionReason::StaleRoots { kind });
    }
    for reference in &observation.references {
        if reference.asset_id == candidate.asset_id {
            if reference.content_digest == candidate.content_digest {
                reasons.push(RetentionReason::Referenced {
                    kind,
                    owner_id: reference.owner_id.clone(),
                });
            } else {
                reasons.push(RetentionReason::IdentityConflict {
                    asset_id: candidate.asset_id.clone(),
                });
            }
        }
    }
}
if candidate.owned_by_operation.as_deref() != Some(context.operation_id.as_str()) {
    reasons.push(RetentionReason::NotOwnedByOperation);
}
reasons.sort_by(|a, b| reason_key(a).cmp(&reason_key(b)));
reasons.dedup();
if reasons.is_empty() {
    Ok(RetentionDecision::EligibleForCleanup {
        asset_id: candidate.asset_id.clone(),
        content_digest: candidate.content_digest.clone(),
    })
} else {
    Ok(RetentionDecision::Retain { reasons })
}
